}

class House {
    private List<Room> rooms;   // rooms belong entirely to this house

    House() {
        rooms = new ArrayList<>();
        rooms.add(new Room("Bedroom"));
        rooms.add(new Room("Kitchen"));
    }

    void destroy() {
        System.out.println("House destroyed, and its rooms cease to exist too");
        rooms = null;
